var tm = TerrainManager
var poly = PackedVector2Array([Vector2(7, 38) * 40.0, Vector2(19, 38) * 40.0, Vector2(19, 44) * 40.0, Vector2(7, 44) * 40.0])
tm.terrain_features.append({"id": "sm11e_scen_ruin", "type": "ruins", "polygon": poly, "height_category": "tall"})
return tm.terrain_features.size()

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[sm11e log] ", DebugLogger.get_real_log_file_path(), " ERROR lines = ", n, " ", bad.slice(0, 3))
return n
